class Resource extends Base {
 mount(){this.data??={name:'',email:'',type:'Website',budget:'Exploring',notes:''};this.step=0;this.done=false;this.render(`<section class="scene panel"><header><span class="label">A GOOD BRIEF IS A GOOD BEGINNING</span><h2>${escape(this.text('label','Start something considered.'))}</h2><p class="hint">A few useful questions. A clearer place to begin.</p></header><nav aria-label="Brief progress"><ol>${['About you','The project','Review'].map((title,i)=>`<li><span>0${i+1}</span><strong>${title}</strong></li>`).join('')}</ol></nav><form></form><div class="submitted" hidden aria-live="polite"></div></section>`,`.scene{min-height:510px;padding:32px;background:var(--bg)}h2{font:400 clamp(28px,4vw,39px) Georgia;letter-spacing:-1px;margin:13px 0}nav{margin:29px 0 25px}ol{display:flex;list-style:none;padding:0;margin:0;gap:9px}li{flex:1;border-top:2px solid var(--line);padding-top:12px;display:flex;align-items:center;gap:8px;color:var(--muted)}li.active{border-top-color:var(--accent);color:var(--ink)}li span{font:10px ui-monospace}li strong{font-size:10px;font-weight:500}form .fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}label{display:flex;flex-direction:column;gap:10px;font-size:11px}label.full{grid-column:1/-1}input,select,textarea{width:100%;font-size:13px}textarea{resize:vertical;min-height:100px}.field-note{font-size:9px;line-height:1.8;color:var(--muted);margin-top:13px}.form-footer{display:flex;align-items:center;justify-content:space-between;gap:15px;padding-top:23px;border-top:1px solid var(--line);margin-top:25px}.form-footer .hint{font-size:9px}.form-footer button{font-size:11px}.review{display:grid;grid-template-columns:1fr 1fr;gap:18px}.review dt{font-size:8px;letter-spacing:1px;color:var(--muted);margin-bottom:7px;text-transform:uppercase}.review dd{margin:0;font-size:12px;overflow-wrap:anywhere}.review>div:last-child{grid-column:1/-1}.review>div:last-child dd{line-height:1.8;white-space:pre-wrap}.submitted{padding:25px;border:1px solid #a4be9333;background:#c6e6b008;border-radius:12px}.submitted[hidden]{display:none}.submitted>span{font-size:27px;color:var(--accent)}.submitted h3{font:400 27px Georgia;margin:15px 0}.submitted p{font-size:12px;color:var(--muted);line-height:1.9}.submitted button{margin-top:22px;font-size:11px}@media(max-width:480px){.scene{padding:25px 20px}form .fields{grid-template-columns:1fr}.review{grid-template-columns:1fr}li{gap:5px}li strong{font-size:8px}.form-footer{flex-wrap:wrap}.form-footer .hint{width:100%;order:3}}`);this.listen(this.$('form'),'input',e=>{if(e.target.name)this.data[e.target.name]=e.target.value;});this.listen(this.$('form'),'change',e=>{if(e.target.name)this.data[e.target.name]=e.target.value;});this.listen(this.$('form'),'submit',e=>{e.preventDefault();if(!this.$('form').reportValidity())return;if(this.step<2){this.step++;this.draw();queueMicrotask(()=>this.$('form input,form select,form textarea,form button[type=submit]')?.focus());}else this.submit();});this.listen(this.$('form'),'click',e=>{if(e.target.closest('[data-back]')){this.step=Math.max(0,this.step-1);this.draw();}});this.listen(this.$('.submitted'),'click',e=>{if(e.target.closest('[data-reset]'))this.reset();});this.draw();}
 draw(){this.$$('nav li').forEach((node,i)=>{node.classList.toggle('active',i<=this.step);if(i===this.step)node.setAttribute('aria-current','step');else node.removeAttribute('aria-current');});let fields;if(this.step===0)fields=`<div class="fields"><label>Your name<input name="name" autocomplete="name" minlength="2" maxlength="70" required value="${escape(this.data.name)}"/></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="120" required value="${escape(this.data.email)}"/></label></div><p class="field-note">Your details stay in this browser example. Nothing is sent to a server.</p>`;else if(this.step===1)fields=`<div class="fields"><label>What are you making?<select name="type">${['Website','Product','Identity','Something else'].map(v=>`<option ${this.data.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Budget stage<select name="budget">${['Exploring','Under 5k','5k–15k','15k+'].map(v=>`<option ${this.data.budget===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">A little context<textarea name="notes" maxlength="1000" placeholder="What would a good outcome look like?">${escape(this.data.notes)}</textarea></label></div>`;else fields=`<dl class="review">${[['Name',this.data.name],['Email',this.data.email],['Project',this.data.type],['Budget stage',this.data.budget],['Context',this.data.notes||'No extra notes.']].map(([label,value])=>`<div><dt>${label}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>`;this.$('form').innerHTML=fields+`<div class="form-footer">${this.step?'<button class="secondary" type="button" data-back>← Previous</button>':'<span class="hint">A thoughtful start takes a moment.</span>'}<button type="submit" class="primary">${this.step===2?'Create brief':'Continue'} ↗</button></div>`;this.$('form').hidden=this.done;}
 get value(){return{...this.data};}
 reset(){this.data={name:'',email:'',type:'Website',budget:'Exploring',notes:''};this.step=0;this.done=false;this.$('.submitted').hidden=true;this.draw();}
 submit(){if(!this.data.name.trim()||!/^\S+@\S+\.\S+$/.test(this.data.email))return false;this.done=true;this.$('form').hidden=true;this.$('.submitted').hidden=false;this.$('.submitted').innerHTML=`<span aria-hidden="true">✓</span><h3>A clearer place to begin.</h3><p>Your ${escape(this.data.type.toLowerCase())} brief is prepared, ${escape(this.data.name.split(' ')[0])}. The details are ready for the next conversation.</p><button class="secondary" data-reset>Create another brief ↗</button>`;this.emit('brief-submit',this.value);return true;}
 configured(name){if(name==='label')this.$('h2').textContent=this.text('label','Start something considered.');}
}
